"""English lessons 11-18 and 20."""
from scripts.case_authoring.schema import A, L, O

PLAIN = 'Clear everyday English. Natural, not formal.'

LESSONS = [
 L('english-11', 'social', 'intermediate', 'A fictional chat between friends about a memorable day.',
   '{{name}} has just told you about {{their_day}}, and now wants to hear a story of yours. Tell {{name}} about a day you remember clearly. Use your own story.',
   "That's enough about {{their_day}}! Tell me about a day you still remember clearly. What happened?",
   'Friend', 'You are telling a friend a story from your own life.', 'Say when and where it happened, tell the events in order, and say how it ended.',
   'Your friend could retell your story: when it was, what happened in order, and how it ended.',
   [A('{{name}}', 'Friend', 'A good friend who loves stories', 'To hear a good story, and to understand what it felt like.', 'Curious, a good listener.', PLAIN, ['Ask what happened next', 'Never invent details of the learner\'s story'], ['story', 'happened', 'then', 'day'])],
   ["The story comes from the learner's own life. {{name}} knows only what the learner says about it.", ('{{name}} recently had {{their_day}}.', 'p1')],
   [O('Find out when and where it happened.', 'The learner sets the past time or place.', 'Last summer, I was in Murree with my cousins.', ['When was this?', 'Where were you?'],
      'Tell me a true story from your own life. Start with when it was, for example: Last year.', 'Telling the listener when and where before the action.', 'Starting in the middle of the action', 'Start with a time: Last year, or: When I was ten.', 'Last summer, I was in Murree with my cousins.', 'Say: Last year, and one thing.', 'grammar'),
    O('Follow the events in order.', 'The learner sequences events in the past.', 'Then the road closed, and after that we had to walk.', ['Then what happened?', 'What did you do next?'],
      'Now tell me what happened, in order. Use words like: then, and: after that.', 'Sequence words, with past verbs, help the listener follow.', 'Mixing present and past', 'Use past verbs: went, saw, had.', 'Then the road closed, so after that we walked.', 'Say: Then I.', 'vocabulary'),
    O('Find out how it ended.', 'The learner explains how the story ended.', 'In the end, we got home late, but it was worth it.', ['So how did it end?', 'What happened in the end?'],
      'Finish your story. Start with: In the end.', 'A clear ending makes a story feel complete.', 'Stopping with no ending', 'Finish with: In the end, or: Finally.', 'In the end, we got home late, but we were happy.', 'Say: In the end.', 'comprehension')],
   'What a story. Thanks for telling me.',
   [{'name': 'Hassan', 'their_day': 'a terrible day at the airport'}, {'name': 'Emma', 'their_day': 'a funny day at my sister\'s wedding'}]),

 L('english-12', 'social', 'intermediate', 'A fictional conversation between friends arranging to meet.',
   'You want to do something with {{name}} this weekend. Invite {{name}}, talk about your plans, and agree the details. {{name}} has plans too, so listen carefully.',
   'Hi! How are things? I was thinking about the weekend. Are you doing anything?',
   'Friend', 'You are inviting a friend to do something this weekend.', 'Make an invitation, talk about what you plan to do, and agree the day and time.',
   'You both know exactly what you are doing, on what day, and at what time.',
   [A('{{name}}', 'Friend', 'A friend with a busy weekend', 'To see you, around the plans already in the diary.', 'Friendly, and a little disorganized.', PLAIN, ['Mention the time that does not work', 'Ask what exactly you will do, and when'], ['weekend', 'saturday', 'sunday', 'plan', 'time'])],
   ['You are arranging something to do together this weekend.', ('{{name}} is {{free}}.', 'p1'), ('{{name}} is busy {{busy}}.', 'p1'), ('{{name}} enjoys {{enjoys}}.', 'p1')],
   [O('Hear the invitation.', 'The learner invites the friend to do something.', 'Would you like to go out on Saturday?', ['Did you want to do something together?', 'Do you have an idea for the weekend?'],
      'You want to invite me to do something. You can say: Would you like to.', 'A clear, friendly invitation with an activity.', 'Saying only: Are you free?', 'Use: Would you like to, or: How about.', 'Would you like to go for a walk this weekend?', 'Say: Would you like to.', 'vocabulary'),
    O('Discuss what you will do.', 'The learner uses future language.', "I'm going to book a table. We'll meet near the park.", ['What are you planning to do?', 'So what will we do exactly?'],
      'Tell me your plan. Use: I am going to, or: we will.', 'Using going to for plans, and will for things decided now.', 'Using the present for future plans', 'Say: I am going to, or: We will.', "I'm going to book a table, and we'll eat after the walk.", 'Say: We will.', 'grammar'),
    O('Agree the details.', 'The learner agrees a day and a time, taking the friend\'s availability into account.', 'How about Saturday at four? That works for me.', ['What day and time should we say?', 'So when exactly shall we meet?'],
      'Now agree the day and time. I told you when I am busy. You can say: How about Saturday at four?', 'Saying the final day and time so that nobody is confused.', 'Ending with: See you sometime', 'Say the day and the time out loud.', 'How about Saturday at four? See you by the gate.', 'Say a day and a time.', 'comprehension')],
   'Perfect. See you then!',
   [{'name': 'Zain', 'free': 'free on Saturday afternoon', 'busy': 'all day on Sunday', 'enjoys': 'walking in the park'}, {'name': 'Priya', 'free': 'free on Sunday morning', 'busy': 'on Saturday', 'enjoys': 'visiting the library and good coffee'}]),

 L('english-13', 'service', 'intermediate', 'A fictional support call about a broken home internet connection.',
   'Your home internet has not worked since {{since}}. You call {{name}} at support. You have already {{tried}}. Explain the problem and check you understand the solution.',
   'Thanks for contacting support, this is {{name}}. What problem are you experiencing?',
   'Customer', 'You are a customer calling internet support.', 'Say exactly what is wrong, say what you have already tried, and confirm the solution.',
   '{{name}} understands the problem, and you can repeat what to do next.',
   [A('{{name}}', 'Support agent', 'Answers calls for the internet provider', 'To find the real problem quickly, without repeating steps you already tried.', 'Calm and methodical.', 'Clear, polite support language. Explains one step at a time.', ['Ask what the lights on the router show', 'Ask what they already tried', 'Ask them to repeat the fix'], ['internet', 'router', 'light', 'error', 'connection'])],
   ['The internet stopped working {{since}}.', 'The customer has already {{tried}}.', ('The router needs {{fix}}.', 'p1'), ('A technician visit would take two working days, if the fix does not work.', 'p1')],
   [O('Find out precisely what is wrong.', 'The learner states the problem specifically.', "The problem is that my internet stopped working last night.", ['Can you tell me what exactly stopped working?', 'What happens when you try to connect?'],
      'You called me because your internet is broken. Tell me what is wrong. Start with: The problem is.', 'A precise description saves time for both of you.', "Saying only: It doesn't work", 'Say what, since when, and what you see.', 'The problem is that my internet stopped working last night.', 'Say: The problem is.', 'vocabulary'),
    O('Find out what has been tried.', 'The learner says what they already tried.', "I've already restarted the router.", ['Have you tried anything yet?', 'What have you done so far?'],
      'Tell me what you already tried. Use: I have tried, or: I already.', 'Using the present perfect for what you have done so far.', 'Saying: I already try', "Say: I've tried, or: I have already.", "I've already restarted it twice.", "Say: I've tried.", 'grammar'),
    O('Check that the solution is understood.', 'The learner confirms the solution in their own words.', 'So I should reset it and wait, is that correct?', ['The next step is {{fix}}. Does that make sense?', 'Can you tell me what you are going to do?'],
      'I told you the next step. Now say it back to me. Start with: So I should.', 'Saying back the solution avoids a second call.', 'Saying okay without understanding', 'Say: So I should, then ask: Is that correct?', 'So I should reset it and wait two minutes, is that correct?', 'Say: So I should.', 'comprehension')],
   "That's right. Thanks for calling, and I hope that solves it.",
   [{'name': 'Farah', 'since': 'last night', 'tried': 'restarted the router twice', 'fix': 'a full reset using the small button on the back'}, {'name': 'Ben', 'since': 'this morning', 'tried': 'checked that the cable is plugged in', 'fix': 'a new settings update, sent from the support system'}]),

 L('english-14', 'colleague', 'intermediate', 'A fictional office where the learner trains a new coworker.',
   '{{name}} started today and needs to learn how to {{process}}. The steps are: {{steps}} Walk {{name}} through it, check understanding, and correct a misunderstanding politely.',
   "I'm new to this. Could you walk me through how to {{process}}?",
   'Experienced coworker', 'You are showing a new coworker how to do a task.', 'Explain the steps in order, check that your coworker understands, and politely correct any mistake.',
   '{{name}} can repeat the steps correctly.',
   [A('{{name}}', 'New coworker', 'Started today', 'To learn this properly, and not to look foolish on day one.', 'Keen and slightly nervous.', PLAIN, ['Repeat one step back slightly wrong, so it can be corrected', 'Ask what happens next'], ['step', 'first', 'next', 'form', 'system'])],
   ['{{name}} needs to learn how to {{process}}.', 'The steps are: {{steps}}', ('{{name}} used a different system at a previous job.', 'p1')],
   [O('Learn the steps in order.', 'The learner explains steps using sequence words.', 'First, open the form. Next, fill in the date.', ['So what do I do first?', 'And after that?'],
      'I am new, and you are showing me how to {{process}}. The steps are in your brief. Start with: First.', 'Sequence words make instructions easy to follow.', 'Giving all the steps in one long sentence', 'Use: First, next, then, finally.', 'First, open the form. Next, fill in the date.', 'Say: First.', 'vocabulary'),
    O('Be checked for understanding.', 'The learner checks understanding.', 'Does that make sense so far?', ['Okay. I think so.', 'Right. Sorry, it is my first day.'],
      'Check that I understood you. You can ask: Does that make sense?', 'Pausing to check, before going on.', 'Going on without checking', 'Ask: Does that make sense? or: Any questions?', 'Does that make sense so far? Any questions?', 'Say: Does that make sense?', 'comprehension'),
    O('Be corrected kindly.', 'The learner politely corrects a misunderstanding.', 'Not quite. Actually, you send it after you save it.', ['So I send it first, and then I save it?', 'So I can skip the first step?'],
      'I made a mistake just now. Please correct me politely. You can say: Not quite. Actually.', 'Correcting the mistake, not the person.', "Saying: No, that's wrong", 'Say: Not quite, or: Actually, and then the right step.', 'Not quite. Actually, you save it first, and then you send it.', 'Say: Not quite.', 'grammar')],
   'Thanks, that really helps. I think I can do it now.',
   [{'name': 'Tariq', 'process': 'submit an expense claim', 'steps': 'open the expenses form, add the receipt photo, choose your manager, then press submit.'},
    {'name': 'Grace', 'process': 'book a meeting room', 'steps': 'open the calendar, choose the room, add the people, then confirm the booking.'}]),

 L('english-15', 'colleague', 'intermediate', 'A fictional lunchtime discussion between colleagues about a current workplace question.',
   '{{name}} wants your opinion on {{question}} {{name}} thinks {{view}}. Say what you think, give two reasons or examples, and respond fairly to the other view.',
   "Here's a question for you: {{question}} I think {{view}}. What's your opinion?",
   'Colleague', 'You are discussing an opinion with a colleague.', 'State your opinion clearly, support it with two reasons or examples, and acknowledge the other view.',
   '{{name}} knows your opinion and your reasons, and feels you listened to their view.',
   [A('{{name}}', 'Discussion partner', 'A colleague who enjoys a friendly debate', 'A real discussion, and to test your reasoning.', 'Thoughtful, happy to disagree politely.', PLAIN, ['Give one reason for your own view', 'Ask for an example'], ['opinion', 'reason', 'example', 'think'])],
   ['The question is: {{question}}', ('{{name}} thinks {{view}}, mainly because {{reason}}.', 'p1')],
   [O('Hear the opinion.', 'The learner states a clear opinion.', 'I think it is better, in my opinion.', ['So what do you think?', 'Which side are you on?'],
      'I asked your opinion. Start with: I think, or: In my opinion.', 'A clear position in the first sentence.', 'Saying only: It depends', 'Say: I think, or: In my opinion.', 'In my opinion, it depends on the job, but mostly I prefer it.', 'Say: I think.', 'vocabulary'),
    O('Hear reasons or examples.', 'The learner supports their opinion with reasons or examples.', 'One reason is cost. For example, travel is expensive.', ['Why do you think so?', 'Can you give me an example?'],
      'Now give me two reasons or examples. Start with: One reason is.', 'Reasons and examples make an opinion worth listening to.', 'Repeating the opinion louder', 'Say: One reason is, and: For example.', 'One reason is cost. For example, my travel takes two hours.', 'Say: One reason is.', 'grammar'),
    O('Have your view acknowledged.', 'The learner acknowledges the other view.', 'I see your point, but I still think that...', ['But what about what I said?', "Don't you think I have a point?"],
      'I have a different view. Show that you heard it. Start with: I see your point, but.', 'Showing you heard the other side, before you answer it.', 'Ignoring the other view', 'Say: I see your point, but.', 'I see your point about cost, but I still think it is worth it.', 'Say: I see your point.', 'comprehension')],
   "Fair enough. That's a good way to look at it.",
   [{'name': 'Ali', 'question': 'is working from home better than working in an office?', 'view': 'the office is better', 'reason': 'new staff learn faster in person'},
    {'name': 'Rachel', 'question': 'should meetings have a strict time limit?', 'view': 'every meeting should stop at thirty minutes', 'reason': 'people get more focused with a limit'}]),

 L('english-16', 'colleague', 'intermediate', 'A fictional Monday morning in an office kitchen.',
   '{{name}} is making coffee on Monday morning. {{name}} {{weekend}}. Make natural small talk, ask follow-up questions, and move smoothly to work: you need {{ask}}.',
   'Morning! Coffee? How was your weekend?',
   'Coworker', 'You are chatting with a coworker before work starts.', 'Open naturally, ask a follow-up question, and then move smoothly to the work topic.',
   'The chat felt natural, you showed interest, and you got to your work question.',
   [A('{{name}}', 'Coworker', 'Works on your team', 'A friendly start to the day, and to get to the desk on time.', 'Chatty and relaxed.', 'Casual, natural workplace English with contractions.', ['Share a little, and wait to be asked more', 'Answer a work question once it comes'], ['weekend', 'coffee', 'project', 'family'])],
   [('{{name}} {{weekend}}.', 'p1'), 'You need {{ask}}.', ('{{name}} can help with that today.', 'p1')],
   [O('Open the chat.', 'The learner responds or opens naturally.', 'Morning! It was good, thanks. How was yours?', ['Did you do anything nice?', 'Good weekend, then?'],
      "We're just chatting in the kitchen. Tell me something about your weekend, and ask about mine.", 'Answering briefly, and returning the question.', 'A long answer, or just: Fine', 'Answer in a few words, then ask: How was yours?', 'Good, thanks. How was yours?', 'Say: How was yours?', 'vocabulary', signal=r"\b(?:how was|how is|did you|good morning|morning|how about you)\b"),
    O('Be asked a follow-up.', 'The learner asks a real follow-up question.', 'Oh nice, where did you go?', ['Yeah, it was great, actually.', 'It was a really nice change.'],
      "I told you about my weekend. Ask me something more about it. You can say: Oh, where did you go?", 'A follow-up shows that you were listening.', 'Changing the subject straight away', 'Pick one detail and ask about it.', 'Oh nice, who did you go with?', 'Ask me one question.', 'comprehension', signal=r"\b(?:where did|who did|what did|how did|did you|was it|what was)\b"),
    O('Move to work smoothly.', 'The learner makes a natural transition to work.', 'By the way, about the report, could you...?', ['Anyway, I should probably get to my desk.', 'Right, big week ahead. Anything I can do for you?'],
      'Now move to your work question. Start with: By the way.', 'A small phrase makes the change of topic feel natural.', 'Changing topic with no signal', 'Say: By the way, or: Speaking of work.', 'By the way, could you send me that file today?', 'Say: By the way.', 'grammar')],
   'No problem, I will sort that out. Have a good one!',
   [{'name': 'Jamal', 'weekend': 'went camping with friends, and it rained the whole time', 'ask': 'the latest sales figures'}, {'name': 'Nora', 'weekend': 'took her parents to the beach for the first time', 'ask': 'a copy of the meeting notes'}]),

 L('english-17', 'meeting', 'intermediate', 'A fictional quick update between a team member and a team lead.',
   'You work on {{task}}. {{status}} The blocker is that {{blocker}}. {{name}}, your team lead, stops by for a quick update. Give the status, explain the blocker without blame, and commit to a next step.',
   'Can you give me a quick update on {{task}}?',
   'Team member', 'You are giving your team lead a quick status update.', 'Lead with the current status, explain the blocker without blaming anyone, and commit to a next step.',
   '{{name}} knows where things stand, what is blocking you, and what you will do next.',
   [A('{{name}}', 'Team lead', 'Your manager', 'A fast, honest status, without having to dig for it.', 'Busy, fair and practical.', PLAIN, ['Ask whose job the blocker is, if someone is blamed', 'Ask by when'], ['status', 'blocker', 'task', 'deadline'], 'Needs to warn the client if the date moves.')],
   ['The work is {{task}}.', 'Status: {{status}}', 'Blocker: {{blocker}}.', ('{{name}} can help if asked: {{help}}.', 'p1')],
   [O('Hear the status first.', 'The learner opens with the current status.', 'The current status is that it is about 80 percent finished.', ['So where are we?', 'Is it on track?'],
      'I just need a quick update. Start with where things are now.', 'Starting with the status, so your lead does not need to ask.', 'Starting with the history', 'First sentence: the status.', 'The current status is that it is mostly done, with one thing open.', 'Say: The current status is.', 'vocabulary'),
    O('Hear the blocker without blame.', 'The learner explains the blocker factually, without blaming a person.', "I'm waiting for the login details, so I can't test yet.", ['Is anything holding it up?', 'What is in the way?'],
      'Tell me what is holding it up. Describe the problem, not the person.', 'Describing the situation, not who is at fault.', "Saying: It's because he didn't", "Say: I'm waiting for, or: The blocker is.", "The blocker is that I'm still waiting for the login details.", 'Say: The blocker is.', 'grammar'),
    O('Hear the next step.', 'The learner commits to a specific next step.', 'Next, I will chase them today and finish by Thursday.', ['So what happens next?', 'And by when?'],
      'Now tell me what you will do next, and by when. Start with: Next, I will.', 'A clear commitment, with a time.', 'Saying: I will try', 'Say: I will, and a day.', 'Next, I will chase them today, and finish by Thursday.', 'Say: Next, I will.', 'comprehension')],
   "Okay, that's clear. Thanks for the update.",
   [{'name': 'Sophie', 'task': 'the customer report', 'status': 'It is about 80 percent complete.', 'blocker': 'the finance figures have not arrived yet', 'help': 'asking finance directly'},
    {'name': 'Kamal', 'task': 'the website update', 'status': 'It is one day behind.', 'blocker': 'the test login does not work', 'help': 'requesting a new login'}]),

 L('english-18', 'colleague', 'intermediate', 'A fictional conversation with a worried colleague in a quiet corner of the office.',
   '{{name}} looks worried and comes to talk to you about {{worry}}. You do not need to solve it. Listen, show that you understand, and ask a useful question.',
   "I'm worried that {{worry}}. I don't know what to do.",
   'Colleague', 'You are listening to a worried colleague.', 'Acknowledge how they feel, say their main concern in your own words, and ask a useful follow-up question.',
   '{{name}} feels heard, and has said more about what is really worrying them.',
   [A('{{name}}', 'Concerned colleague', 'Works with you', 'To be heard, more than to be told what to do.', 'Anxious but open, and closes up if given quick advice.', PLAIN, ["Say 'that's not really it' if the summary is wrong", 'Open up more when listened to'], ['worried', 'team', 'schedule', 'overload'], '{{need}}')],
   ['{{name}} has come to talk to you in a quiet corner of the office.', ('{{name}} is worried that {{worry}}.', 'p1'), ('{{need}}', 'p1', 1)],
   [O('Feel heard.', 'The learner acknowledges the speaker and how they feel.', 'That sounds really stressful. I understand.', ['I just feel like nobody has noticed.', 'Sorry, I know you are busy.'],
      "I'm worried and I want someone to listen. You don't need to fix it. Say something like: That sounds stressful.", 'Showing you heard the feeling, before anything else.', 'Jumping straight to advice', 'Say: That sounds, or: I understand.', 'That sounds really stressful.', 'Say: That sounds hard.', 'vocabulary'),
    O('Hear the concern repeated.', 'The learner paraphrases the main concern in their own words.', "So you're concerned that the team can't cope?", ['Do you see what I mean?', 'I am not sure I am explaining it well.'],
      'Now say what I told you, in your own words. Start with: So you are worried that.', 'Saying it back in your own words shows real listening.', "Repeating the exact words like a parrot", "Say: So you're concerned about, or: It sounds like.", "So you're concerned that the team can't cope with it?", 'Say: So you are worried about.', 'comprehension', min_turns=1),
    O('Be asked a useful question.', 'The learner asks a relevant follow-up question.', 'What would help most right now?', ['I just do not know where to start.', 'I do not know what would help.'],
      'Ask me one useful question. You could ask: What would help most?', 'An open question helps the person think, without you taking over.', 'Asking a question that is really advice', 'Start with: What, or: How.', 'What worries you most about it?', 'Say: What would help?', 'grammar')],
   'Thank you. I feel better just having talked about it.',
   [{'name': 'Hina', 'worry': 'the new schedule is going to overload our team', 'need': 'Hina has been covering for an absent colleague for a month and has not told anyone.'},
    {'name': 'Mark', 'worry': 'my project will be cancelled after the reorganization', 'need': 'Mark has a family to support and fears for his job, but finds that hard to say.'}]),

 L('english-20', 'meeting', 'intermediate', 'A fictional planning meeting, chaired by the learner, for an onboarding workshop.',
   'You chair a meeting with {{a}} and {{b}} to plan a {{length}}-minute onboarding workshop for {{people}} new colleagues next Friday. Agree an agenda, task owners and preparation steps.',
   "I'm {{a}}, the project coordinator, and {{b}} is our training facilitator. We're planning a {{length}}-minute onboarding workshop for {{people}} colleagues next Friday. What should they be able to do afterwards?",
   'Meeting chair', 'You are chairing a planning meeting.', 'Contribute at least one useful idea, respond to both colleagues, and finish with a decision about the plan.',
   'There is a shared decision on the agenda and on who does what.',
   [A('{{a}}', 'Project coordinator', 'Plans the logistics', 'An agenda that fits the room booking and the budget.', 'Organized and time-aware.', PLAIN, ['Bring up time and room limits', 'Ask for a decision'], ['goal', 'schedule', 'time', 'agenda', 'room', 'budget', 'deadline']),
    A('{{b}}', 'Training facilitator', 'Runs the session', 'Enough paired practice so that new colleagues can really do the task.', 'Enthusiastic about practice.', PLAIN, ['Propose a demonstration and paired practice', 'Offer to prepare the materials'], ['tasks', 'demo', 'demonstration', 'practice', 'materials'])],
   ['The workshop is for {{people}} new colleagues next Friday and lasts {{length}} minutes.', 'The goal is for each new colleague to complete one basic product task independently and know where to ask for help.', 'The room is available from 09:00 to 11:00 and has one projector.', 'The workshop must include a product demonstration, paired practice and questions. The spending limit is USD {{budget}}.',
    ('{{a}} can arrange the room and send the agenda.', 'p1'), ('{{b}} suggests a 20-minute demonstration and 40 minutes of paired practice, and can prepare the materials.', 'p2')],
   [O('Hear an idea from the chair.', 'The learner contributes a useful idea for the plan.', 'I suggest we spend most of the time on paired practice.', ['So what do you suggest we prioritise?', 'What is your idea for the first part?'],
      "You're chairing this planning meeting. Suggest one idea for the workshop. You can say: I suggest we.", 'Bringing your own idea, with a reason.', 'Only asking others what to do', 'Say: I suggest we, then: because.', 'I suggest we start with a short demonstration, because people learn by doing.', 'Say: I suggest we.', 'vocabulary'),
    O('Have both colleagues engaged.', 'The learner responds to or invites both speakers.', '{{a}}, does that fit the room? {{b}}, what do you think?', ['I think the demonstration should be short.', 'Does that fit the room booking, though?'],
      'We each have a view. Ask each of us by name what we think.', 'Bringing both people in, by name.', 'Talking to only one person', 'Ask each person by name: What do you think?', '{{a}}, does that fit the room? {{b}}, what do you think?', 'Ask {{b}}: What do you think?', 'comprehension', second=('p2', 'I would keep the demonstration short, so people get most of the time for paired practice.'), driver=1),
    O('Reach a decision.', 'The learner states a shared decision.', 'So we agree: demo first, then paired practice. {{a}} sends the agenda.', ['So what have we decided?', 'Who does what, then?'],
      'Time to decide. Say what we agree, and who does what. Start with: So we agree.', 'Saying the decision out loud so nobody leaves unsure.', 'Ending without a decision', 'Say: So we agree, and name the owners.', 'So we agree: demonstration first, then paired practice. {{a}} sends the agenda.', 'Say: So we agree.', 'grammar')],
   "Good. That's a clear plan. Thanks for chairing.",
   [{'a': 'Alex', 'b': 'Maya', 'length': '90', 'people': '12', 'budget': '300'}, {'a': 'Sara', 'b': 'Yusuf', 'length': '60', 'people': '8', 'budget': '200'}]),
]
